//! Organizationally Unique Identifier lookups from the IEEE MA-L registry.
//!
//! The table is generated by `tools/gen-names` from the registry's public
//! CSV. Only the factual 24-bit assignment and organization name are kept;
//! the short wire label is derived here because the registry has no such
//! column.

include!("oui_data.rs");

/// The broadcast address's resolved label.
const BROADCAST: &str = "Broadcast";

/// Look up the organization name registered for a 24-bit OUI prefix.
pub fn organization(oui: u32) -> Option<&'static str> {
    OUI_NAMES
        .binary_search_by_key(&oui, |(key, _)| *key)
        .ok()
        .and_then(|index| OUI_NAMES.get(index))
        .map(|(_, name)| *name)
}

/// The 24-bit OUI prefix of a MAC address.
pub fn prefix(address: [u8; 6]) -> u32 {
    (u32::from(address[0]) << 16) | (u32::from(address[1]) << 8) | u32::from(address[2])
}

/// Derive Packetfin's short label from a registry organization name.
///
/// The registry carries legal names such as `Cisco Systems, Inc`; the wire
/// label keeps the first word before any comma. The registry itself has no
/// short labels, so this derivation is Packetfin's own.
pub fn short_name(organization: &str) -> &str {
    organization
        .split(',')
        .next()
        .unwrap_or(organization)
        .split_whitespace()
        .next()
        .unwrap_or(organization)
}

/// The long registry name for a MAC address's OUI.
///
/// A broadcast address has no registered organization.
pub fn mac_organization(address: [u8; 6]) -> Option<&'static str> {
    if address == [0xff; 6] {
        return None;
    }
    organization(prefix(address))
}

/// The resolved short label for a MAC address, or `None` for an unknown OUI.
///
/// A broadcast address has a label but no organization. IPv4 and IPv6
/// multicast addresses get the fixed labels `IPv4mcast_...` and
/// `IPv6mcast_...`, with leading zero octets trimmed from the suffix.
pub fn short_label(address: [u8; 6]) -> Option<String> {
    if address == [0xff; 6] {
        return Some(BROADCAST.to_string());
    }
    if let Some(label) = multicast_label(address) {
        return Some(label);
    }
    let organization = organization(prefix(address))?;
    Some(format!(
        "{}_{:02x}:{:02x}:{:02x}",
        short_name(organization),
        address[3],
        address[4],
        address[5]
    ))
}

fn multicast_label(address: [u8; 6]) -> Option<String> {
    let (name, mut first) = match (address[0], address[1], address[2]) {
        (0x01, 0x00, 0x5e) => ("IPv4mcast", 3),
        (0x33, 0x33, _) => ("IPv6mcast", 2),
        _ => return None,
    };
    while first < 5 && address.get(first).copied().unwrap_or(0) == 0 {
        first += 1;
    }
    let mut suffix = String::with_capacity(8);
    for (index, byte) in address.iter().enumerate().skip(first) {
        if index > first {
            suffix.push(':');
        }
        suffix.push_str(&format!("{byte:02x}"));
    }
    Some(format!("{name}_{suffix}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_registry_entries_resolve() {
        assert_eq!(organization(0x00_00_0c), Some("Cisco Systems, Inc"));
        assert_eq!(short_name("Cisco Systems, Inc"), "Cisco");
        assert_eq!(short_name("Apple, Inc."), "Apple");
        assert_eq!(
            short_label([0x00, 0x00, 0x0c, 0x11, 0x22, 0x33]).as_deref(),
            Some("Cisco_11:22:33")
        );
        assert_eq!(
            short_label([0x00, 0x1b, 0x63, 0x01, 0x02, 0x03]).as_deref(),
            Some("Apple_01:02:03")
        );
    }

    #[test]
    fn unknown_and_broadcast_addresses_are_distinguished() {
        assert_eq!(organization(0x02_11_22), None);
        assert_eq!(short_label([0x02, 0x11, 0x22, 0x33, 0x44, 0x55]), None);
        assert_eq!(short_label([0xff; 6]).as_deref(), Some("Broadcast"));
    }

    #[test]
    fn ipv4_and_ipv6_multicast_labels_trim_leading_octets() {
        assert_eq!(
            short_label([0x01, 0x00, 0x5e, 0x00, 0x00, 0x01]).as_deref(),
            Some("IPv4mcast_01")
        );
        assert_eq!(
            short_label([0x01, 0x00, 0x5e, 0x7f, 0x00, 0x01]).as_deref(),
            Some("IPv4mcast_7f:00:01")
        );
        assert_eq!(
            short_label([0x33, 0x33, 0xff, 0x00, 0x00, 0x01]).as_deref(),
            Some("IPv6mcast_ff:00:00:01")
        );
    }

    #[test]
    fn the_table_is_sorted_and_unique() {
        assert!(OUI_NAMES.windows(2).all(|pair| match pair {
            [left, right] => left.0 < right.0,
            _ => true,
        }));
    }
}
